  const error = e => ({name:e && e.name || null,message:scrub(e && e.message || e),type:typeof e});
  try {
  const node=this.template.querySelector('[data-owned-target]');
  const snapshot = () => {
   const current=this.template.querySelector('[data-owned-target]');
   const s=getComputedStyle(current);
   return {color:s.color,backgroundColor:s.backgroundColor,display:s.display,visibility:s.visibility,
    position:s.position,paddingTop:s.paddingTop,width:s.width,hook:s.getPropertyValue('--owned-color').trim(),
    loaded:s.getPropertyValue('--owned-loaded').trim(),className:current.getAttribute('class'),style:current.getAttribute('style')};
  };
