    return settled;
   } catch(e) {events.push({call:n,phase:'synchronous',state:'threw',error:error(e)});return Promise.resolve();}
  };
  const extension=spec.method==='loadStyle'?'.css':'.js';
  const base=assets+'/cases/'+spec.id+'/';
  let url=base+'ok'+extension;
  if (spec.method==='styles') {
   const mode=spec.mode;
   if(mode==='inline') node.style.color='rgb(68, 85, 102)';
   if(mode==='hook_set') this.template.host.style.setProperty('--owned-color','rgb(68, 85, 102)');
   if(mode==='hook_inherited') node.parentElement.style.setProperty('--owned-color','rgb(68, 85, 102)');
