   if(spec.mode==='syntax') url=base+'syntax'+extension;
   if(spec.mode==='throws') url=base+'throws'+extension;
   if(spec.mode==='null') url=null;
   if(spec.mode==='undefined') url=undefined;
   if(spec.mode==='empty') url='';
   if(spec.mode==='number') url=123;
   if(spec.mode==='object') url={toString(){return base+'ok'+extension;}};
