    identity=promises.length>1?promises[0]===promises[1]:null;await Promise.all([first,second]);
   } else {
    await call(url,context);
    if(spec.mode==='sequential2'||spec.mode==='sequential3'||spec.mode==='retry_failure') await call(url,context);
    if(spec.mode==='sequential3') await call(url,context);
    if(spec.mode==='query_changed') await call(url+'?owned=2',context);
